### 🐛 Describe the bug

### Issue

A model that uses torch.cond to choose between two CUDA kernels runs fine eager, but `torch._inductor.aoti_load_package` fails to execute the exported model correctly.

### Repro:
```python
# main.py
import torch
import os
from torch.utils.cpp_extension import load

op = load(name="add_extension", sources=[os.path.join(os.path.dirname(__file__), "op.cu")], verbose=True)

torch.library.define("myops::add_one", "(Tensor x) -> Tensor")
torch.library.define("myops::add_two", "(Tensor x) -> Tensor")
torch.library.impl("myops::add_one", "CUDA", op.add_one)
torch.library.impl("myops::add_two", "CUDA", op.add_two)

@torch.library.register_fake("myops::add_one")
def _(x): return torch.empty_like(x)

@torch.library.register_fake("myops::add_two")
def _(x): return torch.empty_like(x)

class M(torch.nn.Module):
    def forward(self, x):
        # return torch.ops.myops.add_one(x) works totally fine
        return torch.cond(x.shape[0] < 5, torch.ops.myops.add_one, torch.ops.myops.add_two, (x,))

model = M()

exported = torch.export.export(model, (torch.zeros(3, device="cuda"),), dynamic_shapes={"x": {0: torch.export.Dim("batch", min=1, max=128)}})
torch._inductor.aoti_compile_and_package(exported, package_path="model.pt2")
aoti_model = torch._inductor.aoti_load_package("model.pt2")
result = aoti_model(torch.zeros(6, device="cuda"))
print(f"{result = }")
```
```cuda
// op.cu
#include <torch/extension.h>

__global__ void add_k(float* o, const float* i, long n, float v){
    long idx = blockIdx.x * blockDim.x + threadIdx.x;
    if(idx < n) o[idx] = i[idx] + v;
}

torch::Tensor add_impl(torch::Tensor x, float v){
    auto y = torch::empty_like(x);
    long n = x.numel();
    int t = 256;
    int b = (n + t - 1) / t;
    add_k<<<b,t>>>(y.data_ptr<float>(), x.data_ptr<float>(), n, v);
    return y;
}

torch::Tensor add_one(torch::Tensor x){ return add_impl(x,1.0f); }
torch::Tensor add_two(torch::Tensor x){ return add_impl(x,2.0f); }

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m){
    m.def("add_one", &add_one);
    m.def("add_two", &add_two);
}
```

### Expected Behavior

The model should export and compile correctly and have the same behavior as eager mode

### Actual Behavior
```
[E806 16:46:31.818410663 shim_common.cpp:1232] Exception in aoti_torch: Unable to find a proxy executor to run custom ops. Please check if there is a json file generated in the same directory as the so, or use torch._inductor.aoti_compile_and_package to package everything into a PT2 artifact.
result = None
```

Note: without the `torch.cond`, everything works fine.

I might be doing something wrong here, if anyone has ideas for workarounds, please let me know! I thought that `aoti_compile_and_package` should package everything into a single executable.

### Versions

```
Versions of relevant libraries:
[pip3] numpy==2.2.6
[pip3] nvidia-cublas-cu12==12.6.4.1
[pip3] nvidia-cuda-cupti-cu12==12.6.80
[pip3] nvidia-cuda-nvrtc-cu12==12.6.77
[pip3] nvidia-cuda-runtime-cu12==12.6.77
[pip3] nvidia-cudnn-cu12==9.5.1.17
[pip3] nvidia-cufft-cu12==11.3.0.4
[pip3] nvidia-curand-cu12==10.3.7.77
[pip3] nvidia-cusolver-cu12==11.7.1.2
[pip3] nvidia-cusparse-cu12==12.5.4.2
[pip3] nvidia-cusparselt-cu12==0.6.3
[pip3] nvidia-nccl-cu12==2.26.2
[pip3] nvidia-nvjitlink-cu12==12.6.85
[pip3] nvidia-nvtx-cu12==12.6.77
[pip3] torch==2.7.1
[pip3] triton==3.3.1
[conda] Could not collect
```

